#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    ll m;
    cin >> n >> m;

    vector<ll> v(n);
    ll sum = 0;

    for (ll& x : v) {
        cin >> x;
        sum += x;
    }

    if (sum < m) {
        cout << -1;
        return 0;
    }

    sort(v.rbegin(), v.rend());

    auto f = [&](int k) {
        ll res = 0;
        for (int i = 0; i < n; ++i) {
            res += max(0LL, v[i] - i / k);
        }
        return res;
    };

    int left = 1, right = n;

    while (left < right) {
        int mid = left + (right - left) / 2;
        if (f(mid) >= m)
            right = mid;
        else
            left = mid + 1;
    }

    cout << left;
    return 0;
}

